(async () => {
  const status = root.querySelector('[data-status]');
  const items = root.querySelector('[data-items]');
  try {
    const result = await reportAPI.getDataSets();
    if (!Array.isArray(result)) throw new Error('Dataset metadata must be an array');
    items.replaceChildren();
    for (const item of result) {
      const li = document.createElement('li');
      li.textContent = String(item && item.dataSet != null ? item.dataSet : '(unnamed)');
      items.appendChild(li);
    }
    status.textContent = result.length ? `${result.length} datasets available` : 'No datasets available for this account.';
  } catch (e) {
    status.textContent = 'Unable to load datasets: ' + (e && e.message ? e.message : 'Unknown error');
  }
})();
